SELECT 

WHERE n.user_id = #{userId}
  AND n.deleted = 0
ORDER BY n.created_at DESC, n.id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM gn_note n
WHERE n.deleted = 0

    AND n.status = #{status}


    AND n.channel_id = #{channelId}

SELECT 

WHERE n.deleted = 0

    AND n.status = #{status}


    AND n.channel_id = #{channelId}

ORDER BY n.created_at DESC, n.id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT 

JOIN gn_note_like l ON l.note_id = n.id AND l.user_id = #{userId}
WHERE n.deleted = 0
  AND n.status = 2
ORDER BY l.created_at DESC, l.id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT 

JOIN gn_note_collect c2 ON c2.note_id = n.id AND c2.user_id = #{userId}
WHERE n.deleted = 0
  AND n.status = 2
ORDER BY c2.created_at DESC, c2.id DESC
LIMIT #{limit} OFFSET #{offset}

