UPDATE gn_note
SET like_count = like_count + #{delta}
WHERE id = #{id}
  AND deleted = 0
  AND like_count + #{delta} >= 0

UPDATE gn_note
SET collect_count = collect_count + #{delta}
WHERE id = #{id}
  AND deleted = 0
  AND collect_count + #{delta} >= 0

UPDATE gn_note
SET comment_count = comment_count + #{delta}
WHERE id = #{id}
  AND deleted = 0
  AND comment_count + #{delta} >= 0
